import { useSyncExternalStore } from 'react';
import type { BaseClass, Fighter } from '../engine/types';
import { JOBS } from '../data/jobs';

// Image assets live in public/assets (see public/assets/README.md). A manifest of the files actually present is
// served at /assets/manifest.json (generated by the Vite plugin), so nothing is requested unless it exists and
// every image slot falls back to its emoji / glyph when a file is missing.
const BASE = import.meta.env.BASE_URL;
const EXTS = ['png', 'webp', 'gif'];
let files = new Set<string>();
let version = 0;
const listeners = new Set<() => void>();
const subscribe = (cb: () => void) => { listeners.add(cb); return () => { listeners.delete(cb); }; };

export async function loadManifest(): Promise<void> {
  try {
    const res = await fetch(`${BASE}assets/manifest.json`, { cache: 'no-store' });
    const json = await res.json();
    const next = new Set<string>(Array.isArray(json?.files) ? json.files.filter((f: unknown): f is string => typeof f === 'string') : []);
    if (next.size === files.size && [...next].every(f => files.has(f))) return;
    files = next; version++; listeners.forEach(l => l());
  } catch { /* no manifest (e.g. static host without assets): everything falls back to emoji */ }
}
/** Re-render consumers whenever the manifest changes. */
export const useAssets = () => useSyncExternalStore(subscribe, () => version);
export const assetCount = () => files.size;
export const assetUrl = (rel: string) => `${BASE}assets/${rel}`;

function findFile(stem: string): string | null {
  for (const e of EXTS) if (files.has(`${stem}.${e}`)) return assetUrl(`${stem}.${e}`);
  return null;
}
// `x_01.png, x_02.png ...` form an animation; a plain `x.png` is a single frame.
function findFrames(stem: string): string[] {
  const first = findFile(`${stem}_01`);
  if (!first) { const one = findFile(stem); return one ? [one] : []; }
  const out = [first];
  for (let i = 2; i < 100; i++) { const f = findFile(`${stem}_${String(i).padStart(2, '0')}`); if (!f) break; out.push(f); }
  return out;
}

/** True when `<stem>.png` or an animated `<stem>_01.png` set exists (stem is relative to public/assets, no extension). */
export const assetExists = (stem: string) => findFrames(stem).length > 0;

export type SpriteState = 'idle' | 'attack' | 'hit' | 'down' | 'skill' | 'win' | 'portrait';
/** First existing image for any of `dirs` x `states`. Each dir is `category/name`; files are `<name>_<state>.png`. */
export function resolveSprite(dirs: string[], states: SpriteState[]): string[] {
  for (const dir of dirs) {
    const name = dir.split('/').pop()!;
    for (const st of states) { const f = findFrames(`${dir}/${name}_${st}`); if (f.length) return f; }
  }
  return [];
}
export const resolveBackground = (zoneId: string, kind: 'battle' | 'town'): string | null => findFile(`backgrounds/${zoneId}/${kind}`);
export const resolveIcon = (name: string): string | null => findFile(`ui/icons/${name}`);

// ---- naming (matches the image guide: leon / elia / serin, monsters and bosses by template id) ----
export const HERO_FILE: Record<BaseClass, string> = { warrior: 'leon', mage: 'elia', cleric: 'serin' };
export const heroDirs = (baseClass: BaseClass, jobId: string) => [`characters/classes/${jobId}`, `characters/${HERO_FILE[baseClass]}`];
export const monsterDirs = (templateId: string, boss: boolean) => [`${boss ? 'bosses' : 'monsters'}/${templateId}`];
export function fighterDirs(f: Fighter): string[] {
  if (f.side === 'ally') return heroDirs(JOBS[f.job]?.baseClass ?? 'warrior', f.job);
  return monsterDirs(f.templateId ?? f.job, !!f.boss);
}
export const fighterState = (f: Fighter, s: { acting?: boolean; hit?: boolean }): SpriteState => (!f.alive ? 'down' : s.hit ? 'hit' : s.acting ? 'attack' : 'idle');
